head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     Tech Tutorial Custom Theme (DevOpsCube Inspired)
Designer: Custom
----------------------------------------------- */

:root {
  --bg-color: #18181b;
  --text-color: #a1a1aa;
  --heading-color: #ffffff;
  --primary-color: #ff1493;
  --primary-hover: #ff69b4;
  --card-bg: #27272a;
  --border-color: #3f3f46;
  --font-body: 'Inter', sans-serif;
  --font-code: 'Fira Code', monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary-color);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary-hover);
}

h1, h2, h3, h4, h5, h6 {
  color: var(--heading-color);
  font-weight: 700;
  line-height: 1.3;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}

.container {
  max-width: 1400px;
  width: 95%;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  flex-wrap: nowrap; /* Prevent sidebar from wrapping to next line */
  gap: 40px;
}

/* Header Professional */
.site-header {
  background-color: rgba(15, 23, 42, 0.95);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
}

.header-left-col {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.site-title {
  margin: 0;
  line-height: 1;
}

.site-title a {
  color: #ffffff;
  display: flex;
  align-items: center;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
  text-decoration: none;
}

.site-logo-img {
  height: 38px;
  width: auto;
  margin-right: 12px;
  object-fit: contain;
  /* CSS Trick to remove white background on dark header */
  filter: invert(1) brightness(2);
  mix-blend-mode: screen;
}

.header-right-col {
  display: flex;
  align-items: center;
  flex-grow: 1;
  justify-content: flex-end;
}

.header-nav ul {
  list-style: none;
  display: flex;
  gap: 32px;
  margin: 0;
  padding: 0;
  align-items: center;
}

.header-nav li {
  position: relative;
}

.header-nav a {
  color: #94a3b8;
  font-weight: 600;
  font-size: 15px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 24px 0;
  text-decoration: none;
  transition: color 0.2s ease;
}

.header-nav a:hover {
  color: #ffffff;
}

.header-nav a svg {
  opacity: 0.7;
}
.header-nav a:hover svg {
  opacity: 1;
}

.caret {
  transition: transform 0.2s ease;
}

.header-nav li:hover .caret {
  transform: rotate(180deg);
}

/* Dropdown Premium Styling */
.header-nav .dropdown {
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  position: absolute;
  top: 100%;
  left: 0;
  background: #1e293b;
  min-width: 220px;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
  border-radius: 12px;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.05);
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.header-nav li:hover .dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.header-nav .dropdown li {
  width: 100%;
}

.header-nav .dropdown a {
  padding: 10px 16px;
  color: #cbd5e1;
  border-radius: 8px;
}

.header-nav .dropdown a:hover {
  background: rgba(255, 255, 255, 0.05);
  color: #ffffff;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-left: 32px;
  padding-left: 32px;
  border-left: 1px solid rgba(255,255,255,0.1);
}

.search-icon {
  color: #94a3b8;
  transition: color 0.2s ease;
}

.search-icon:hover {
  color: #ffffff;
}

.pro-btn {
  background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
  color: #ffffff !important;
  padding: 10px 20px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 14px;
  text-decoration: none;
  box-shadow: 0 4px 6px -1px rgba(37, 99, 235, 0.2);
  transition: all 0.2s ease;
}

.pro-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 8px -1px rgba(37, 99, 235, 0.3);
  filter: brightness(110%);
}

.mobile-menu-toggle {
  display: none;
  color: #ffffff;
  cursor: pointer;
  padding: 8px;
  border-radius: 6px;
  background: rgba(255,255,255,0.05);
}

.mobile-close-btn {
  display: none;
}

.mobile-overlay {
  display: none;
}

/* Off-Canvas Mobile Menu */
@media (max-width: 900px) {
  .header-inner {
    padding: 0 16px;
  }
  .site-logo-img {
    height: 32px;
    margin-right: 10px;
  }
  .site-title a {
    font-size: 18px;
  }
  .mobile-menu-toggle {
    display: flex;
  }
  .header-actions {
    border-left: none;
    padding-left: 0;
    margin-left: 0;
    width: 100%;
    justify-content: space-between;
    margin-top: auto;
    padding-top: 24px;
  }

  .mobile-overlay {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.6);
    backdrop-filter: blur(4px);
    z-index: 999;
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
  }
  .mobile-overlay.active {
    opacity: 1;
    visibility: visible;
  }

  .header-right-col {
    position: fixed;
    top: 0;
    right: -320px;
    width: 320px;
    max-width: 80vw;
    height: 100vh;
    background: #0f172a;
    z-index: 1001;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    padding: 24px;
    transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -10px 0 25px rgba(0,0,0,0.5);
    overflow-y: auto;
  }

  .header-right-col.open {
    right: 0;
  }

  .mobile-close-btn {
    display: flex;
    align-self: flex-end;
    color: #94a3b8;
    cursor: pointer;
    padding: 8px;
    margin-bottom: 24px;
    background: rgba(255,255,255,0.05);
    border-radius: 8px;
  }

  .header-nav {
    width: 100%;
  }

  .header-nav ul {
    flex-direction: column;
    gap: 0;
    width: 100%;
  }

  .header-nav li {
    width: 100%;
  }

  .header-nav a {
    padding: 16px 0;
    border-bottom: 1px solid rgba(255,255,255,0.05);
  }

  .header-nav .dropdown {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    background: transparent;
    box-shadow: none;
    border: none;
    padding: 0 0 0 24px;
    display: flex;
  }

  .header-nav .dropdown a {
    padding: 12px 0;
    font-size: 14px;
  }
}

/* Hero Section */
.hero-section {
  background-color: #18181b; /* Dark theme hero */
  color: #ffffff;
  padding: 100px 20px;
  text-align: center;
  border-bottom: 1px solid #27272a;
}

.hero-inner {
  max-width: 800px;
  margin: 0 auto;
}

.hero-headline {
  font-size: 48px;
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 24px;
  letter-spacing: -1px;
}

.hero-highlight {
  color: #ff1493;
}

.hero-subheadline {
  font-size: 18px;
  color: #a1a1aa;
  line-height: 1.6;
  margin-bottom: 40px;
}

.hero-subscribe-form {
  display: flex;
  max-width: 450px;
  margin: 0 auto;
}

.hero-subscribe-form input {
  flex: 1;
  padding: 16px 20px;
  border: none;
  border-radius: 6px 0 0 6px;
  font-size: 16px;
  outline: none;
}

.hero-subscribe-form button {
  background-color: #000000;
  color: #ffffff;
  border: none;
  padding: 0 24px;
  border-radius: 0 6px 6px 0;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: background-color 0.2s;
}

.hero-subscribe-form button:hover {
  background-color: #27272a;
}

/* Blog Section Header */
.blog-section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
}

.blog-section-header h2 {
  font-size: 24px;
  color: var(--text-color);
  margin: 0;
}

.blog-section-header a {
  color: #94a3b8;
  text-decoration: none;
  font-weight: 600;
  font-size: 14px;
  transition: color 0.2s;
}

.blog-section-header a:hover {
  color: var(--primary-color);
}

/* Layout Widths */
.main-content {
  flex: 1;
  min-width: 0;
}

.sidebar-area {
  width: 320px;
  flex-shrink: 0;
}

@media (max-width: 1024px) {
  .container {
    flex-wrap: wrap;
  }
  .main-content {
    width: 100%;
  }
  .sidebar-area {
    width: 100%;
    margin-top: 40px;
  }
}

/* Post Card - Horizontal Layout */
.post {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 0;
  margin-bottom: 24px;
  transition: box-shadow 0.3s, transform 0.3s;
  display: flex;
  flex-direction: row;
  overflow: hidden;
}

.post:hover {
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
  transform: translateY(-3px);
}

.post-thumbnail {
  width: 280px;
  min-height: 200px;
  flex-shrink: 0;
  background-color: #3f3f46;
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #71717a;
  font-size: 14px;
}

.post-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.post-content {
  padding: 28px 30px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  flex: 1;
}

@media (max-width: 768px) {
  .hero-headline {
    font-size: 32px;
  }
  .hero-subscribe-form {
    flex-direction: column;
  }
  .hero-subscribe-form input {
    border-radius: 6px;
    margin-bottom: 10px;
  }
  .hero-subscribe-form button {
    border-radius: 6px;
    padding: 16px;
  }
  .post {
    flex-direction: column;
  }
  .post-thumbnail {
    width: 100%;
    min-height: 180px;
  }
}

.post-title {
  font-size: 28px;
  margin-top: 0;
  margin-bottom: 12px;
  line-height: 1.4;
}

.post-title a {
  color: var(--heading-color);
}

.post-title a:hover {
  color: var(--primary-color);
}

.post-meta {
  font-size: 14px;
  color: #9ca3af;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.post-body {
  font-size: 16px;
  color: var(--text-color);
}

.post-body p {
  margin-bottom: 1.2em;
}

.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 4px;
  margin: 20px 0;
  border: 1px solid var(--border-color);
}

/* Code Snippets */
.post-body code {
  font-family: var(--font-code);
  background-color: #f3f4f6;
  color: #b91c1c;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.85em;
}

.post-body pre {
  background-color: #1e293b !important;
  border-radius: 6px;
  padding: 16px !important;
  margin: 20px 0 !important;
  overflow-x: auto;
}

.post-body pre code {
  background-color: transparent;
  padding: 0;
  color: #e2e8f0;
  font-size: 14px;
}

.read-more-btn {
  display: inline-block;
  margin-top: 20px;
  font-weight: 600;
  font-size: 14px;
}

/* Widget Styles */
.widget {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 24px;
  margin-bottom: 30px;
}

.widget h2 {
  font-size: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 0;
  margin-bottom: 20px;
  color: var(--text-color);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 10px;
}

/* Email Capture Form */
.email-capture-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.email-capture-form p {
  font-size: 14px;
  color: #4b5563;
  margin-bottom: 8px;
  line-height: 1.5;
}

.email-capture-form input[type="email"] {
  padding: 10px 14px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  font-family: var(--font-body);
  font-size: 15px;
  outline: none;
  width: 100%;
}

.email-capture-form input[type="email"]:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(26, 86, 219, 0.1);
}

.email-capture-form button {
  background-color: var(--primary-color);
  color: white;
  border: none;
  padding: 12px;
  border-radius: 4px;
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
}

.email-capture-form button:hover {
  background-color: var(--primary-hover);
}

/* Label List Widget */
.list-label-widget-content ul {
  list-style: none;
  padding: 0;
}

.list-label-widget-content li {
  padding: 8px 0;
  border-bottom: 1px dashed var(--border-color);
  font-size: 15px;
}

.list-label-widget-content li:last-child {
  border-bottom: none;
}

.list-label-widget-content a {
  color: #4b5563;
}

.list-label-widget-content a:hover {
  color: var(--primary-color);
}

.list-label-widget-content span {
  float: right;
  color: #9ca3af;
  font-size: 13px;
}

/* Footer Professional */
.site-footer {
  background-color: #0f172a;
  color: #94a3b8;
  padding: 80px 0 40px;
  margin-top: 80px;
  border-top: 1px solid #1e293b;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 60px;
}

@media (max-width: 900px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-col h3 {
  color: #ffffff;
  font-size: 16px;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col ul {
  list-style: none;
  padding: 0;
}

.footer-col ul li {
  margin-bottom: 12px;
}

.footer-col a {
  color: #94a3b8;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--primary-color);
}

.footer-brand p {
  margin-top: 20px;
  line-height: 1.6;
  max-width: 300px;
}

.footer-bottom {
  border-top: 1px solid #1e293b;
  padding-top: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

@media (max-width: 768px) {
  .footer-bottom {
    flex-direction: column;
    gap: 20px;
    text-align: center;
  }
}

/* Widget Title & Content */
.widget-title {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  color: var(--heading-color);
  margin-top: 0;
}

.widget-content {
  margin-bottom: 0;
}

/* Blog Pager - Dark Theme */
.blog-pager {
  display: flex;
  justify-content: space-between;
  margin-top: 30px;
  gap: 16px;
}

.blog-pager a {
  padding: 12px 24px;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--primary-color);
  text-decoration: none;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.2s ease;
}

.blog-pager a:hover {
  background: var(--border-color);
  transform: translateY(-1px);
}

/* Footer Container Fix */
.site-footer .container {
  display: block;
}

/* Popular Posts Widget */
.popular-posts-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.popular-posts-list li {
  padding-bottom: 12px;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.popular-posts-list li:last-child {
  padding-bottom: 0;
  margin-bottom: 0;
  border-bottom: none;
}

.popular-posts-list a {
  color: var(--heading-color);
  font-weight: 500;
  font-size: 15px;
  transition: color 0.2s;
}

.popular-posts-list a:hover {
  color: var(--primary-color);
}

/* Post Labels/Tags */
.post-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 20px;
}

.post-labels a {
  background: var(--border-color);
  color: var(--text-color);
  padding: 4px 14px;
  border-radius: 20px;
  font-size: 13px;
  transition: all 0.2s;
}

.post-labels a:hover {
  background: var(--primary-color);
  color: #fff;
}

/* Error Page */
.error-page {
  text-align: center;
  padding: 100px 20px;
}

.error-page h1 {
  font-size: 72px;
  margin-bottom: 16px;
  color: var(--primary-color);
}

.error-page p {
  font-size: 18px;
  color: var(--text-color);
  margin-bottom: 30px;
}

.error-page a {
  display: inline-block;
  padding: 12px 24px;
  background: var(--primary-color);
  color: #fff;
  border-radius: 8px;
  font-weight: 600;
  transition: all 0.2s;
}

.error-page a:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
}

/* Status Message (search/archive) */
.status-msg-wrap {
  padding: 20px;
  margin-bottom: 20px;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  color: var(--text-color);
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  var mobileBtn = document.getElementById('mobileMenuBtn');
  var closeBtn = document.getElementById('mobileCloseBtn');
  var overlay = document.getElementById('mobileOverlay');
  var headerRight = document.getElementById('headerRightCol');

  function toggleMenu() {
    if(headerRight.classList.contains('open')) {
      headerRight.classList.remove('open');
      overlay.classList.remove('active');
      document.body.style.overflow = '';
    } else {
      headerRight.classList.add('open');
      overlay.classList.add('active');
      document.body.style.overflow = 'hidden';
    }
  }

  if(mobileBtn && closeBtn && overlay && headerRight) {
    mobileBtn.addEventListener('click', toggleMenu);
    closeBtn.addEventListener('click', toggleMenu);
    overlay.addEventListener('click', toggleMenu);
  }
});
//
